import{_ as t,o,c as r,ak as a}from"./chunks/framework.BNVJvTzl.js";const u=JSON.parse('{"title":"Rates & Liabilities Tools","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tools/financials.md","filePath":"reference/tools/financials.md"}'),d={name:"reference/tools/financials.md"};function i(s,e,n,c,l,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="rates-liabilities-tools" tabindex="-1">Rates &amp; Liabilities Tools <a class="header-anchor" href="#rates-liabilities-tools" aria-label="Permalink to &quot;Rates &amp; Liabilities Tools&quot;">​</a></h1><p>All tools in this section are <strong>Owner only</strong> unless stated. See <a href="/reference/concepts/financials.html">Financials &amp; P&amp;L</a> and <a href="/reference/concepts/vendors.html">Vendors &amp; Liabilities</a> for background.</p><hr><h2 id="set_rate" tabindex="-1">set_rate <a class="header-anchor" href="#set_rate" aria-label="Permalink to &quot;set_rate {#set_rate}&quot;">​</a></h2><p>Set a person&#39;s hourly cost. Append-only — creates a new rate record with an effective date.</p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Writes to</strong>: <code>13. Rate_History</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>user_name</code> or <code>user_id</code> or <code>user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>hourly_cost</code></td><td>✅</td><td>In USD, e.g. <code>80</code> for $80/hr</td></tr><tr><td><code>effective_from</code></td><td></td><td><code>YYYY-MM-DD</code> — defaults to today</td></tr></tbody></table><p><strong>Rate versioning</strong>: Setting a new rate never changes historical data. The new rate applies from <code>effective_from</code> forward. Historical P&amp;L calculations automatically use the rate that was effective on each entry&#39;s date.</p><p><strong>Audit</strong>: <code>set_rate</code> does <strong>not</strong> post to the audit channel — financial data is never logged to shared channels. The action is logged to the server console only.</p><p><strong>Disambiguation</strong>: If the workspace has multiple people with the same first name, <code>set_rate</code> will surface a numbered disambiguation menu before proceeding. Natural-language phrasings including possessives (<code>&quot;set Sarah&#39;s rate to $95&quot;</code>) are fully supported. The confirmation paraphrase always uses the person&#39;s full canonical name — never a bare first name.</p><blockquote><p>Rates are strictly owner-only. Never surface, mention, or attempt to access rate data for a Manager or User. Do not reveal that rate data exists unless speaking to an Owner.</p></blockquote><hr><h2 id="get_rates" tabindex="-1">get_rates <a class="header-anchor" href="#get_rates" aria-label="Permalink to &quot;get_rates {#get_rates}&quot;">​</a></h2><p>Current effective hourly cost for all (or one) person. Returns the most recent rate where <code>effective_from ≤ today</code>. <strong>Owner only.</strong></p><p><strong>Reads from</strong>: <code>13. Rate_History</code>, <code>03. Users</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>user_name</code> (optional — omit for all users)</p><hr><h2 id="get_person_rate_history" tabindex="-1">get_person_rate_history <a class="header-anchor" href="#get_person_rate_history" aria-label="Permalink to &quot;get_person_rate_history {#get_person_rate_history}&quot;">​</a></h2><p>All rate rows for a person — full versioned history. <strong>Owner only.</strong></p><p><strong>Reads from</strong>: <code>13. Rate_History</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>user_name</code></p><hr><h2 id="create_liability" tabindex="-1">create_liability <a class="header-anchor" href="#create_liability" aria-label="Permalink to &quot;create_liability {#create_liability}&quot;">​</a></h2><p>Record a fixed payment commitment to a vendor, or to a contractor paid a fixed price, on a project. <strong>Owner only.</strong></p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Writes to</strong>: <code>14. Liabilities</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>project_name</code> or <code>project_id</code></td><td>✅</td><td>Project must be active and have a deadline set; a retainer period needs its start and end instead (a sprint is refused)</td></tr><tr><td><code>vendor_name</code> or <code>vendor_user_id</code></td><td>✅</td><td>A user with <code>employment_type</code> <code>vendor</code>, or <code>contractor</code> on a Fixed Price project or a retainer period</td></tr><tr><td><code>agreed_amount</code></td><td>✅</td><td>Fixed payment in USD</td></tr><tr><td><code>agreed_hours</code></td><td>✅</td><td>Contracted scope in hours (positive number)</td></tr><tr><td><code>description</code></td><td>✅</td><td>What the payment covers</td></tr><tr><td><code>accrual_start</code>, <code>accrual_end</code></td><td></td><td>Console-only. The dates the liability&#39;s hours and cost build up between. Both or neither, real dates, end on or after start (issue 2621). Omitted, the liability accrues from the day it was created to the project deadline (a retainer period&#39;s own window on a period). The console&#39;s Add form fills them with the project&#39;s start date and deadline</td></tr></tbody></table><p><strong>T&amp;M:</strong> a T&amp;M project can&#39;t carry a liability, for a vendor or a contractor: the call is refused with &quot;A T&amp;M project can&#39;t carry a liability: each recorded hour is billed there, and a liability records no hours. Use a Fixed Price project for a fixed fee.&quot; Liabilities made there before this rule are unaffected (issue 2623).</p><p><strong>A contractor&#39;s liability:</strong> refused on any project other than a Fixed Price project or a retainer period, when the contractor already holds an active liability there, or when they have more than one active envelope there. The response&#39;s <code>envelope_needed</code> is <code>true</code> when they have no envelope there yet; the console then creates one (the agreed hours, a chosen task, the description as its label). On a Fixed Price project or a retainer period, the holder&#39;s recorded time on that project is reference only and counts toward none of its hours, revenue or cost.</p><p>When a liability exists for vendor X on project Y, the liability&#39;s <code>agreed_amount</code> becomes the cost for that vendor on that project — overriding the hourly calculation entirely. The <code>agreed_hours</code> value accrues linearly from the liability creation date to the project deadline, contributing to the project&#39;s hours-logged figure in all burn-down and health calculations.</p><hr><h2 id="list_liabilities" tabindex="-1">list_liabilities <a class="header-anchor" href="#list_liabilities" aria-label="Permalink to &quot;list_liabilities {#list_liabilities}&quot;">​</a></h2><p>Vendor payment commitments. <strong>Owner (all) or Manager (own projects only).</strong></p><p><strong>Reads from</strong>: <code>14. Liabilities</code>, <code>02. Projects</code>, <code>03. Users</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td></td></tr><tr><td><code>project_id</code></td><td>Optional filter</td></tr><tr><td><code>vendor_user_id</code></td><td>Optional filter</td></tr><tr><td><code>status</code></td><td><code>&quot;active&quot;</code> (default) or <code>&quot;cancelled&quot;</code></td></tr></tbody></table><p>Each liability in the response includes an <code>implied_hours_to_date</code> field: the pro-rated portion of <code>agreed_hours</code> that has accrued from the creation date (for a retainer period, the period&#39;s start) to today, based on a linear track to the project deadline.</p><p>Each liability also reports <code>accrues_from</code> and <code>accrues_to</code>: the window actually in force (its own accrual dates, a retainer period&#39;s window, or creation to deadline).</p><hr><h2 id="cancel_liability" tabindex="-1">cancel_liability <a class="header-anchor" href="#cancel_liability" aria-label="Permalink to &quot;cancel_liability {#cancel_liability}&quot;">​</a></h2><p>Mark a liability as cancelled. Sets status to <code>&quot;cancelled&quot;</code> — the record is never deleted. <strong>Owner only.</strong></p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Updates</strong>: <code>14. Liabilities</code> col F</p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>liability_id</code></p><p><strong>A contractor&#39;s liability with its envelope (issue 2597)</strong> cancels that envelope too. The response&#39;s <code>cancelled_allocation_id</code> names it (null when there was none).</p><h2 id="update_liability" tabindex="-1">update_liability <a class="header-anchor" href="#update_liability" aria-label="Permalink to &quot;update_liability {#update_liability}&quot;">​</a></h2><p>Edit an active liability&#39;s description, agreed amount, or agreed hours. Cancelled liabilities cannot be edited. <strong>Owner only.</strong> Audit carries no dollar figure (rule 21).</p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>liability_id</code> (required); <code>agreed_amount</code>, <code>agreed_hours</code>, <code>description</code>, <code>accrual_start</code>, <code>accrual_end</code> (at least one required)</p><p>The accrual dates are console-only and presence-based: send both to set them, both as empty strings to clear them (back to the earlier rule), never one alone (issue 2621).</p><p>At least one of the optional fields must be supplied. The project must have a deadline set, or, for a retainer period, a start and end.</p><p><strong>A contractor&#39;s liability with its envelope (issue 2597):</strong> a change to <code>agreed_hours</code> changes the envelope&#39;s hours, and a change to <code>description</code> its label (the first 40 characters). New agreed hours below the hours already placed in the envelope&#39;s weekly plan are refused; reduce the plan first. The response&#39;s <code>budget_id</code> names the envelope.</p>',55)])])}const _=t(d,[["render",i]]);export{u as __pageData,_ as default};
